/**
 * Mushaf page data and QCF v2 page fonts.
 *
 * Reference (DEC-089): the King Fahd Complex Madani Mushaf, 15 lines per page,
 * 604 pages, set in the official QCF v2 per-page glyph fonts.
 *
 * Both halves of that reference now ship with the app. `public/data/mushaf` is
 * generated by `scripts/prepare-mushaf-pages.mjs` and carries the reference
 * line numbers *and* the `code_v2` glyph for every word, so turning a page no
 * longer costs a call to api.quran.com — it used to cost one request plus an
 * 1800 ms abort timer before the page could settle. Only the page font is still
 * remote, and it is kept in Cache Storage after its first load so that repeat
 * and offline reads are instant.
 */

import { promoteMushafRequest, scheduleMushafRequest, type MushafPriority } from "./mushafScheduler";

export type MushafWordTuple = [
  position: number,
  lineNumber: number,
  isEnd: number,
  semanticText: string,
  qcfCode?: string,
];

export interface MushafVerseData {
  k: string;
  w: MushafWordTuple[];
}

const QCF_FONT_ROOT = "https://verses.quran.foundation/fonts/quran/hafs/v2/woff2";
export const FONT_CACHE_NAME = "azkar-qcf-fonts-v1";
export const MUSHAF_CACHE_NAME = "azkar-mushaf-v3";
const MAX_MEMORY_PAGES = 128;

const pageCache = new Map<number, MushafVerseData[]>();
const pendingPages = new Map<number, Promise<MushafVerseData[]>>();
const readyFonts = new Set<number>();
const pendingFonts = new Map<number, Promise<boolean>>();
const decodedFonts = new Map<number, FontFace>();
const pinnedFonts = new Map<number, number>();
const MAX_DECODED_FONTS = 12;

function trimDecodedFonts(except?: number) {
  for (const [page, face] of decodedFonts) {
    if (decodedFonts.size <= MAX_DECODED_FONTS) break;
    if (page === except || pinnedFonts.has(page)) continue;
    document.fonts?.delete?.(face);
    decodedFonts.delete(page);
    readyFonts.delete(page);
  }
}

/** Mounted readers own leases; eviction never removes their matching page font. */
export function retainQcfFonts(pages: readonly number[]) {
  const unique = [...new Set(pages.filter((page) => page >= 1 && page <= 604))];
  for (const page of unique) pinnedFonts.set(page, (pinnedFonts.get(page) ?? 0) + 1);
  return () => {
    for (const page of unique) {
      const count = pinnedFonts.get(page) ?? 0;
      if (count <= 1) pinnedFonts.delete(page);
      else pinnedFonts.set(page, count - 1);
    }
    queueMicrotask(() => trimDecodedFonts());
  };
}

export function getMushafMemoryStats() {
  return {
    decodedFonts: decodedFonts.size,
    pinnedFonts: pinnedFonts.size,
    fontLimit: MAX_DECODED_FONTS,
    parsedPages: pageCache.size,
  };
}

export function getMushafPageUrl(page: number) {
  const base = import.meta.env.BASE_URL || "/";
  return `${base.endsWith("/") ? base : `${base}/`}data/mushaf/${page}.json${[42, 49, 75, 76, 207, 603, 604].includes(page) ? "" : "?v=3"}`;
}

export function getQcfFontUrl(page: number) {
  if ([42, 49, 75, 76, 207, 603, 604].includes(page)) {
    const base = import.meta.env.BASE_URL || "/";
    return `${base.endsWith("/") ? base : `${base}/`}fonts/qcf-v2/2026-10-11/p${page}.woff2`;
  }
  return `${QCF_FONT_ROOT}/p${page}.woff2`;
}

export function getQcfFontFamily(page: number) {
  return `qcf-v2-page-${page}`;
}

/** Rejects anything that is not the shipped page shape, so a truncated or
 *  mis-served file falls back rather than rendering a broken page. */
export function parseMushafPage(value: unknown): MushafVerseData[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;

  const parsed: MushafVerseData[] = [];
  for (const verse of value) {
    if (!verse || typeof verse !== "object") return null;
    const { k, w } = verse as { k?: unknown; w?: unknown };
    if (typeof k !== "string" || !Array.isArray(w) || w.length === 0) return null;

    const words: MushafWordTuple[] = [];
    for (const word of w) {
      if (!Array.isArray(word)) return null;
      const [position, lineNumber, isEnd, text, qcfCode] = word as unknown[];
      if (
        typeof position !== "number" ||
        typeof lineNumber !== "number" ||
        lineNumber < 1 ||
        lineNumber > 15 ||
        typeof isEnd !== "number" ||
        typeof text !== "string"
      ) {
        return null;
      }
      words.push(
        typeof qcfCode === "string"
          ? [position, lineNumber, isEnd, text, qcfCode]
          : [position, lineNumber, isEnd, text],
      );
    }
    parsed.push({ k, w: words });
  }

  return parsed;
}

/** Validate derived offline resources before publishing or trusting a cache hit. */
export async function readMushafPageResponse(response: Response): Promise<MushafVerseData[] | null> {
  if (response.status !== 200) return null;
  try {
    return parseMushafPage(await response.clone().json());
  } catch {
    return null;
  }
}

export async function readQcfFontResponse(response: Response): Promise<ArrayBuffer | null> {
  if (response.status !== 200) return null;
  try {
    const bytes = await response.clone().arrayBuffer();
    if (bytes.byteLength < 48) return null;
    const header = new DataView(bytes);
    // WOFF2 signature, complete declared file length and at least one table.
    if (header.getUint32(0) !== 0x774f4632 || header.getUint32(8) !== bytes.byteLength || header.getUint16(12) === 0)
      return null;
    return bytes;
  } catch {
    return null;
  }
}

/** A page renders in QCF only when every one of its words carries a glyph. A
 *  half-glyph page would mix two typefaces on the same line. */
export function pageHasQcfGlyphs(page: readonly MushafVerseData[]): boolean {
  return page.every((verse) => verse.w.every((word) => typeof word[4] === "string" && word[4].length > 0));
}

/** A facing spread must use one glyph system on both pages. */
export function resolveSpreadQcfMode(primary: boolean, facing: boolean | undefined): boolean {
  return facing === undefined ? primary : primary && facing;
}

export function getCachedMushafPage(page: number): MushafVerseData[] | undefined {
  return pageCache.get(page);
}

export function isQcfFontReady(page: number): boolean {
  return readyFonts.has(page);
}

/** Synchronous first paint only when its canonical glyph mode is already ready. */
export function getReadyMushafPage(page: number) {
  const data = getCachedMushafPage(page);
  if (!data) return null;
  const qcf = pageHasQcfGlyphs(data);
  return qcf && !isQcfFontReady(page) ? null : { page, data, qcf };
}

function rememberPage(page: number, data: MushafVerseData[]) {
  pageCache.delete(page);
  pageCache.set(page, data);
  while (pageCache.size > MAX_MEMORY_PAGES) {
    const oldest = pageCache.keys().next().value;
    if (oldest === undefined) break;
    pageCache.delete(oldest);
  }
}

/**
 * Deliberately unabortable. The same promise is shared by the reader and by the
 * neighbour prefetch, so letting one consumer's AbortSignal cancel it would let
 * a fast double tap cancel the page the reader is about to show.
 */
export function loadMushafPage(page: number, priority: MushafPriority = "foreground"): Promise<MushafVerseData[]> {
  const cached = pageCache.get(page);
  if (cached) return Promise.resolve(cached);

  const pending = pendingPages.get(page);
  if (pending) {
    promoteMushafRequest(`page:${page}`, priority);
    return pending;
  }

  const request = (async () => {
    const url = getMushafPageUrl(page);
    let cache: Cache | undefined;

    if (typeof caches !== "undefined") {
      try {
        cache = await caches.open(MUSHAF_CACHE_NAME);
        const response = await cache.match(url);
        if (response) {
          const parsed = await readMushafPageResponse(response);
          if (parsed) {
            rememberPage(page, parsed);
            return parsed;
          }
          await cache.delete(url);
        }
      } catch {
        /* Unavailable storage must not prevent a bounded online recovery. */
      }
    }

    const response = await scheduleMushafRequest(`page:${page}`, () => fetch(url), priority);
    if (!response.ok) throw new Error(`Mushaf page ${page} request failed with HTTP ${response.status}`);
    const parsed = await readMushafPageResponse(response);
    if (!parsed) throw new Error(`Mushaf page ${page} did not match the expected shape`);
    try {
      await cache?.put(url, response);
    } catch {
      /* Reading remains available when storage is full. */
    }
    rememberPage(page, parsed);
    return parsed;
  })().finally(() => {
    pendingPages.delete(page);
  });

  pendingPages.set(page, request);
  return request;
}

export function canonicalAyahText(pages: ReadonlyArray<ReadonlyArray<MushafVerseData>>, verseKey: string) {
  const words = new Map<number, string>();
  for (const page of pages) {
    for (const verse of page) {
      if (verse.k !== verseKey) continue;
      for (const [position, , isEnd, text] of verse.w) {
        if (!isEnd) words.set(position, text);
      }
    }
  }
  return [...words.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, text]) => text)
    .join(" ");
}

/**
 * Loads the complete reviewed Uthmani ayah, including the rare case where an
 * ayah crosses a page boundary. QCF glyphs are never copied: they are private
 * code points for drawing, while this returns the semantic text shipped beside
 * each word.
 */
export async function loadCanonicalAyahText(verseKey: string, pageNumber: number) {
  const pages = new Map<number, MushafVerseData[]>();
  const current = await loadMushafPage(pageNumber);
  if (!current.some((verse) => verse.k === verseKey)) throw new Error(`Ayah ${verseKey} is not on page ${pageNumber}`);
  pages.set(pageNumber, current);

  let previousPage = pageNumber;
  while (previousPage > 1 && pages.get(previousPage)?.[0]?.k === verseKey) {
    previousPage -= 1;
    const previous = await loadMushafPage(previousPage);
    pages.set(previousPage, previous);
    if (previous.at(-1)?.k !== verseKey) break;
  }

  let nextPage = pageNumber;
  while (nextPage < 604 && pages.get(nextPage)?.at(-1)?.k === verseKey) {
    nextPage += 1;
    const next = await loadMushafPage(nextPage);
    pages.set(nextPage, next);
    if (next[0]?.k !== verseKey) break;
  }

  const text = canonicalAyahText(
    [...pages.entries()].sort(([a], [b]) => a - b).map(([, page]) => page),
    verseKey,
  );
  if (!text) throw new Error(`Ayah ${verseKey} has no semantic text`);
  return text;
}

async function openFontCache(): Promise<Cache | null> {
  if (typeof caches === "undefined") return null;
  try {
    return await caches.open(FONT_CACHE_NAME);
  } catch {
    return null;
  }
}

async function createFontFace(page: number, priority: MushafPriority): Promise<FontFace> {
  const family = getQcfFontFamily(page);
  const primaryUrl = getQcfFontUrl(page);
  const cache = await openFontCache();

  if (cache) {
    try {
      let response = await cache.match(primaryUrl);
      if (response) {
        const bytes = await readQcfFontResponse(response);
        if (bytes) return new FontFace(family, bytes);
        await cache.delete(primaryUrl);
        response = undefined;
      }
      if (!response) {
        const network = await scheduleMushafRequest(`font:${page}`, () => fetch(primaryUrl), priority);
        const bytes = await readQcfFontResponse(network);
        if (bytes) {
          await cache.put(primaryUrl, network.clone()).catch(() => undefined);
          return new FontFace(family, bytes);
        }
      }
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") throw error;
      /* Fall through to the plain URL source below. */
    }
  }

  return new FontFace(family, `url(${primaryUrl})`);
}

export function loadQcfFont(page: number, priority: MushafPriority = "foreground"): Promise<boolean> {
  if (page < 1 || page > 604) return Promise.resolve(false);

  if (typeof FontFace === "undefined" || typeof document === "undefined" || !document.fonts) {
    readyFonts.add(page);
    return Promise.resolve(true);
  }
  if (readyFonts.has(page)) {
    const face = decodedFonts.get(page);
    if (face) {
      decodedFonts.delete(page);
      decodedFonts.set(page, face);
    }
    return Promise.resolve(true);
  }

  const pending = pendingFonts.get(page);
  if (pending) {
    promoteMushafRequest(`font:${page}`, priority);
    return pending;
  }

  const request = (async () => {
    try {
      const face = await createFontFace(page, priority);
      const loaded = await face.load();
      document.fonts.add(loaded);
      readyFonts.add(page);
      decodedFonts.set(page, loaded);
      trimDecodedFonts(page);
      return true;
    } catch (error) {
      if (error instanceof DOMException && error.name === "AbortError") return false;
      // A structurally complete WOFF2 file can still fail browser decoding.
      // Remove only that derived font so the next explicit attempt can recover.
      try {
        await (await openFontCache())?.delete(getQcfFontUrl(page));
      } catch {
        /* Storage failures must not hide the readable fallback. */
      }
      return false;
    }
  })().finally(() => {
    pendingFonts.delete(page);
  });

  pendingFonts.set(page, request);
  return request;
}

/**
 * Caches this app no longer routes anything to.
 *
 * DEC-089 dropped the two Workbox runtime routes that fed them, and Workbox
 * only tidies up its own precache — so every browser that had visited before
 * that release still carries them, holding page data we now ship and fonts we
 * now store ourselves. Nothing reads them again, so they are pure dead weight
 * in the reader's storage quota.
 */
const RETIRED_CACHES = ["azkar-qcf-page-data-v1", "azkar-qcf-page-fonts-v1", "azkar-mushaf-v1", "azkar-mushaf-v2"];

export async function discardRetiredCaches(): Promise<string[]> {
  if (typeof caches === "undefined") return [];
  const discarded: string[] = [];
  for (const name of RETIRED_CACHES) {
    try {
      if (await caches.delete(name)) discarded.push(name);
    } catch {
      /* A browser that will not let go of a cache is not worth failing over. */
    }
  }
  return discarded;
}

/**
 * Makes one page fully ready for the reader. The local page JSON and its QCF
 * font start together, so the slower cross-origin font does not wait behind
 * parsing work. Callers with strong navigation intent may await this; ordinary
 * look-ahead uses the non-blocking wrapper below.
 */
export async function prepareMushafPage(page: number, priority: MushafPriority = "foreground"): Promise<boolean> {
  if (page < 1 || page > 604) return false;
  const [, fontReady] = await Promise.all([loadMushafPage(page, priority), loadQcfFont(page, priority)]);
  return fontReady;
}

/** Choose the typeface once before painting this visit. Late fonts warm the next visit. */
export async function resolveMushafPage(page: number, loadPageFont = true) {
  const font = loadPageFont ? loadQcfFont(page).catch(() => false) : Promise.resolve(false);
  const data = await loadMushafPage(page);
  if (!loadPageFont || !pageHasQcfGlyphs(data)) return { page, data, qcf: false };
  if (isQcfFontReady(page)) return { page, data, qcf: true };
  return { page, data, qcf: await waitForQcfFont(font) };
}

export async function waitForQcfFont(font: Promise<boolean>) {
  let timeout: ReturnType<typeof setTimeout> | undefined;
  try {
    return await Promise.race([
      font,
      new Promise<boolean>((resolve) => {
        timeout = setTimeout(() => resolve(false), 1200);
      }),
    ]);
  } finally {
    clearTimeout(timeout);
  }
}

/** Warms a neighbouring page without ever surfacing its failure. */
export function prefetchMushafPage(page: number, priority: "next" | "prefetch" = "next") {
  if (typeof document !== "undefined" && document.hidden) return;
  void prepareMushafPage(page, priority).catch(() => undefined);
}
